import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { api, formatApiError } from "../lib/api";
import { useAuth } from "../lib/auth";
import { toast } from "sonner";
import LoadingSpinner from "../components/LoadingSpinner";
import CommentThread from "../components/CommentThread";

export default function TheoryPage() {
  const { id } = useParams();
  const { user } = useAuth();
  const [t, setT] = useState(null);
  const [voteLoading, setVoteLoading] = useState(null);

  useEffect(() => {
    api.get(`/theories/${id}`).then((r) => setT(r.data));
  }, [id]);

  const castVote = async (type) => {
    if (!user) return;
    setVoteLoading(type);
    try {
      const r = await api.post(`/theories/${id}/${type}`);
      setT(r.data);
      toast.success(type === "support" ? "co-signed" : "pushed back");
    } catch (e) {
      toast.error(formatApiError(e.response?.data?.detail));
    } finally {
      setVoteLoading(null);
    }
  };

  if (!t) return <div className="px-6 py-20 meta-ink">loading...</div>;

  return (
    <article className="max-w-3xl mx-auto px-6 py-16">
      <div className="meta-ink mb-3">
        theory / {t.stance} / by{" "}
        {t.author ? (
          <Link to={`/c/${t.author}`} className="underline">
            @{t.author}
          </Link>
        ) : (
          "anonymous"
        )}
      </div>
      <h1 className="font-display font-black text-4xl md:text-6xl tracking-tighter leading-[0.95]">{t.title}</h1>
      <div className="flex flex-wrap gap-3 mt-5 items-center">
        {t.album_id && <Link to={`/album/${t.album_id}`} className="tag-chip">album / {t.album_id}</Link>}
        <span className="tag-chip" style={{ background: "var(--acid)" }}>
          {t.supporters} co-sign
        </span>
        <span className="tag-chip" style={{ background: "#FFD479" }}>
          {t.challengers} push back
        </span>
        {user ? (
          <div className="flex flex-wrap gap-2">
            <button
              className="brutal-btn accent"
              type="button"
              onClick={() => castVote("support")}
              disabled={voteLoading !== null}
            >
              {voteLoading === "support" ? <><LoadingSpinner size={16} /> <span className="ml-2">co-signing</span></> : "co-sign"}
            </button>
            <button
              className="brutal-btn"
              type="button"
              onClick={() => castVote("challenge")}
              disabled={voteLoading !== null}
            >
              {voteLoading === "challenge" ? <><LoadingSpinner size={16} /> <span className="ml-2">pushing back</span></> : "push back"}
            </button>
          </div>
        ) : (
          <span className="meta-ink">log in to vote</span>
        )}
      </div>
      <div className="mt-10 editorial-prose dropcap">
        <p>{t.abstract}</p>
      </div>
      <CommentThread
        targetType="theory"
        targetId={t.id}
        initialCount={t.replies || t.comments || 0}
      />
    </article>
  );
}
